query.base:
TS metrics-gcp.cloudsql_postgresql.otel-*
| WHERE gcp.resource_type == "cloudsql_database"
// For fleets with read replicas. replica_lag (seconds) is reported on the REPLICA
// instance only. If no replica has ever reported, the replica fields are unmapped and
// the query fails with "Unknown column": the rule does not apply to that fleet.
// MIN(MIN_OVER_TIME) and MAX(MAX_OVER_TIME) are exact across fragments.
// PostgreSQL engine marker: num_backends on the replica itself, or the PostgreSQL-only
// replica_byte_lag that the PRIMARY reports with attributes.replica_name set to the
// replica's instance name. Some PostgreSQL replicas report no postgresql/* metrics,
// so the primary's link keeps them covered while MySQL / SQL Server replicas match neither.
| STATS lag_min = MIN(MIN_OVER_TIME(`cloudsql.googleapis.com/database/replication/replica_lag`)),
        lag_max = MAX(MAX_OVER_TIME(`cloudsql.googleapis.com/database/replication/replica_lag`)),
        lag_n = SUM(COUNT_OVER_TIME(`cloudsql.googleapis.com/database/replication/replica_lag`)),
        pg = SUM(COUNT_OVER_TIME(`cloudsql.googleapis.com/database/postgresql/num_backends`)),
        pg_link = SUM(COUNT_OVER_TIME(`cloudsql.googleapis.com/database/postgresql/replication/replica_byte_lag`))
    BY database_id, project_id, attributes.replica_name
// Attribute the primary's replica_byte_lag rows to the replica (database_id is
// "<project_id>:<instance>"; read replicas live in the primary's project).
| EVAL database_id = COALESCE(CONCAT(project_id, ":", attributes.replica_name), database_id)
| STATS lag_min = MIN(lag_min),
        lag_max = MAX(lag_max),
        lag_n = SUM(lag_n),
        pg = SUM(pg),
        pg_link = SUM(pg_link)
    BY database_id

breach.segment:
WHERE (pg > 0 OR pg_link > 0) AND lag_n > 0
// Require ~5 minutes of lag samples so one late sample cannot trigger
| WHERE lag_n >= 5
// Alert threshold (seconds): the replica stayed behind its primary for the WHOLE
// window (the minimum lag is above the threshold), i.e. it is not catching up
// after bursts. Lower for latency-sensitive read traffic; raise for cross-region
// replicas or batch-heavy primaries.
| WHERE lag_min >= 120
| KEEP database_id, lag_min, lag_max
| SORT lag_min DESC
| LIMIT 100
